    },
    {
      "headline": "Tomio Okamura draws attention in new role as Parliamentary Speaker",
      "summary": "Coverage of Speaker Okamura's positions on EU restrictions, Ukrainian refugees, and his increased media engagement. Includes his statement that EU prevents Czech Republic from tightening Ukrainian refugee policies and criticism from opposition."
    },
    {
      "headline": "Renowned musician and pedagogue Pavel Klikar dies at 72",
      "summary": "Pavel Klikar, founder of the Original Prague Syncopated Orchestra and musicologist specializing in early jazz and baroque music, passed away. He was considered a pioneer in authentic interpretation of both classical jazz and baroque music."
    },
